            if (res.status !== 200) throw new Error("Failed to delete member");

            setMembers((prev) => prev.filter((m) => m.member_id !== member_id));
            toast.success("Member deleted successfully!");
            if (currentMemberRows.length === 1 && currentPage > 1) {
